{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Fludarabine, a 2-fluoroadenine nucleoside sharing the same purine base as the query, has dose-independent oral bioavailability of approximately 55% in patients, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Fludarabine monophosphate, a water-soluble prodrug of the same 2-fluoroadenine nucleoside, shows 70% absolute oral bioavailability in humans, indicating efficient intestinal absorption of this polar scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Clofarabine, a 2-halogenated adenine nucleoside analog, has absolute oral bioavailability of 49% in patients, supporting transfer of high oral bioavailability to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Cladribine, another 2-halogenated adenine deoxyribonucleoside, has oral bioavailability of about 35% in a population PK analysis and 37-55% in other studies, confirming that this nucleoside class is orally bioavailable despite high polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "MK-8591, a 2-fluoroadenine nucleoside analog, is characterized by high oral bioavailability, reinforcing the class-level evidence for efficient oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "A single record reports 10% oral bioavailability for a closely related 2-fluoroadenine nucleoside, but this conflicts with multiple other records for the same molecule showing 50-75% and is likely formulation-specific or an outlier.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a 2-fluoroadenine ribonucleoside. Multiple close structural analogs—fludarabine (~55%), fludarabine phosphate (70%), clofarabine (49%), cladribine (35-55%), and MK-8591 (high)—demonstrate that this polar nucleoside class is efficiently absorbed orally, likely via nucleoside transporters, giving F well above 20%. The single low record (10%) is an outlier and outweighed by consistent higher estimates. Prediction: high.",
  "evidence_gaps": [
    "No direct oral bioavailability data for the exact query molecule.",
    "The closest analog has only moderate Morgan similarity (0.64), and differences in sugar stereochemistry/substitution may affect transporter affinity and metabolism.",
    "One conflicting low-bioavailability record for the closest analog introduces uncertainty, though it is inconsistent with multiple other records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

